export type ReviewRoundKind =
  | "external-browser"
  | "internal-api"
  | "internal-cc"
  | "skill-improvement"
  | "closure-wave"
  | "ext-closure";

export type PaperId = "P1A" | "P1B" | "P2" | "P3" | "P4" | "P5";
/**
 * Paper ids that may appear in a {@link ReviewRound}'s `papers` list. This is a
 * superset of {@link PaperId}: it adds "P1U" (the unified Paper 1) which is an
 * active review target but is not one of the six papers keyed by the historical
 * `Record<PaperId, …>` verdict/gap matrices below, so it deliberately does NOT
 * widen `PaperId` (that would require a P1U column in every one of those
 * matrices).
 */
export type RoundPaperId = PaperId | "P1U";

export interface ReviewRoundLink {
  label: string;
  href: string;
}

export interface GapMetric {
  /** Findings only the external tier caught — the internal/external gap. */
  externalOnlyFindings: number;
  note: string;
}

/**
 * One event on the review-activity timeline. ALL strings are ONE-LINE only —
 * long-form round reports live as markdown files under site/public/reviews/
 * and render at /reviews/<reportSlug>.
 */
export interface ReviewRound {
  id: string;
  kind: ReviewRoundKind;
  dateISO: string;
  /** Optional PT time window for cadence visibility on the timeline. */
  timePT?: string;
  title: string;
  papers: RoundPaperId[];
  summary: string;
  keyTakeaways: string[];
  gapMetric?: GapMetric;
  links: ReviewRoundLink[];
  /** Slug of a markdown report at /reviews/<slug> (file: public/reviews/<slug>.md). */
  reportSlug?: string;
}

